using namespace std;using V=array<int,24>;int dp(const V&a,const V&b){int z=0;for(int i=0;i<24;i++)z+=a[i]*b[i];return z;}int H[]={3,-2,2,-1,1};vector<V>E[5];V v;mt19937 rng(40);V w;int num[7][7];vector<V> X,Y;void put(V a){int k=dp(a,v)/8,l=dp(a,w)/8;assert(abs(k)<=3&&abs(l)<=3);num[k+3][l+3]++;if(k==2&&l==1)X.push_back(a);if(k==1&&l==2)Y.push_back(a);assert(dp(a,a)==32);int h=dp(a,v);assert(h%8==0);for(int i=0;i<5;i++)if(h==8*H[i])E[i].push_back(a);}
bool edge(int i,const V&a,int j,const V&b){int d=H[i]-H[j];return 12*dp(a,b)>=8*(25-d*d);}
vector<pair<int,V>> A;int best=0;int calls;bool rec(int t){if(t>best){best=t;cout<<"best "<<best+1<<endl;for(auto [j,a]:A){cout<<H[j]<<" : ";for(int k:a)cout<<k<<" ";cout<<endl;}}if(t==5)return true;if(++calls>20000)return false;for(auto &a:E[t]){bool ok=true;for(auto &[j,b]:A)if(!edge(t,a,j,b)){ok=false;break;}if(!ok)continue;A.emplace_back(t,a);if(rec(t+1))return true;A.pop_back();if(calls>20000)break;}return false;}
int main(){v.fill(1);v[0]=5;for(int j:{0,1,5,6,7,9,11,23})w[j]=2;w[1]-=4;w[5]-=4;w[0]-=4;w[2]+=4;assert(dp(w,v)==0&&dp(w,w)==48);for(int i=0;i<24;i++)for(int j=0;j<i;j++)for(int a:{-4,4})for(int b:{-4,4}){V z{};z[i]=a;z[j]=b;put(z);}int cnt=0;for(int k=0;k<4096;k++){int w=0,g=(1<<11)|(1<<9)|(1<<7)|(1<<6)|(1<<5)|(1<<1)|1;for(int j=0;j<12;j++)if(k>>j&1)w^=g<<j;w|=__builtin_parity(w)<<23;if(__builtin_popcount(w)==8){vector<int>s;for(int j=0;j<24;j++)if(w>>j&1)s.push_back(j);for(int m=0;m<256;m++)if(!__builtin_parity(m)){V z{};for(int j=0;j<8;j++)z[s[j]]=(m>>j&1)?-2:2;put(z);}}for(int j=0;j<24;j++){V z;for(int l=0;l<24;l++)z[l]=w>>l&1?-1:1;z[j]*=-3;put(z);}}
for(auto x:X)for(auto y:Y)if(dp(x,y)==-8){for(int i=0;i<24;i++)cout<<x[i]+y[i]<<" ";cout<<endl;goto done;}assert(false);done:for(int i=-3;i<=3;i++){for(int j=-3;j<=3;j++)cout<<num[i+3][j+3]<<" ";cout<<endl;}}

